package com.bank.risk.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Best contiguous profit run allowing at most one day to be excluded.
public class ResilientStreakAnalyzer {
    private static final Logger log = Logger.getLogger(ResilientStreakAnalyzer.class.getName());

    public long bestStreakWithOneExcludedDay(int[] pnl) {
        if (pnl == null || pnl.length == 0) {
            throw new IllegalArgumentException("P&L sequence must be non-empty");
        }
        long noDel = pnl[0];       // best run ending here, no deletion used
        long oneDel = Long.MIN_VALUE; // best run ending here, one deletion used
        long globalMax = pnl[0];

        for (int i = 1; i < pnl.length; i++) {
            int x = pnl[i];
            long prevNoDel = noDel;
            // Deleting x from the previous no-deletion run == prevNoDel.
            // Extending a run that already deleted one == oneDel + x.
            oneDel = Math.max(prevNoDel, (oneDel == Long.MIN_VALUE ? Long.MIN_VALUE : oneDel + x));
            noDel = Math.max(x, prevNoDel + x);
            long bestHere = Math.max(noDel, oneDel);
            globalMax = Math.max(globalMax, bestHere);
            final int day = i;
            final long nd = noDel;
            final long od = oneDel;
            log.fine(() -> "Day " + day + ": noDel=" + nd + " oneDel="
                    + (od == Long.MIN_VALUE ? "n/a" : od));
        }
        final long result = globalMax;
        log.info(() -> "Best resilient streak over " + Arrays.toString(pnl) + " = " + result);
        return globalMax;
    }
}
